"""Response registry.

:class:`ResponseRegistry` replaces the ``domain.responses`` dict from v1.
It is loaded from ``responses.yml`` files (one project-level file, optional
per-skill files merged on top).
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, NamedTuple

import structlog
import yaml  # type: ignore[import-untyped]
from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from rasa.exceptions import ValidationError
from rasa.mantle.skills.conditions import (
    ConditionEvaluationError,
    evaluate_expression,
)
from rasa.mantle.skills.prose_scoping import is_empty_prose_if_condition

structlogger = structlog.get_logger()

_INVALID_RESPONSES_MAPPING_CODE = "responses.registry.invalid_mapping"
_INVALID_RESPONSE_ENTRY_CODE = "responses.registry.invalid_entry"
_INVALID_RESPONSE_VARIANT_CODE = "responses.registry.invalid_variant"

RESPONSES_YAML_KEY = "responses"
RESPONSES_FILENAME = "responses.yml"
VARIANT_TEXT_KEY = "text"
VARIANT_METADATA_KEY = "metadata"
VARIANT_CONDITION_KEY = "condition"
VARIANT_BUTTONS_KEY = "buttons"
VARIANT_BUTTONS_SOURCE_KEY = "source"
BUTTON_TITLE_KEY = "title"
BUTTON_PAYLOAD_KEY = "payload"
METADATA_REPHRASE_KEY = "rephrase"

# Keys permitted on a response variant mapping in responses.yml; unknown keys
# (e.g. channel, dynamic_buttons) are rejected at parse time.
ALLOWED_VARIANT_KEYS = frozenset(
    {
        VARIANT_TEXT_KEY,
        VARIANT_METADATA_KEY,
        VARIANT_CONDITION_KEY,
        VARIANT_BUTTONS_KEY,
    }
)

# Keys permitted on each static button mapping in responses.yml.
ALLOWED_BUTTON_KEYS = frozenset({BUTTON_TITLE_KEY, BUTTON_PAYLOAD_KEY})
ALLOWED_BUTTON_SOURCE_KEYS = frozenset({VARIANT_BUTTONS_SOURCE_KEY})


class ResponseButton(BaseModel):
    """One static button on a response variant (label plus optional tap payload)."""

    model_config = ConfigDict(frozen=True)

    title: str
    """Label shown on the button."""
    payload: str | None = None
    """Tap payload string, or ``None`` when omitted in YAML.

    :func:`~rasa.mantle.orchestration.memory_utils.resolve_response_buttons`
    fills omitted payloads from the resolved title before delivery.
    """

    @field_validator("title")
    @classmethod
    def _validate_title_non_empty(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("Button title must be non-empty.")
        return value

    @field_validator("payload")
    @classmethod
    def _validate_payload_non_empty_when_set(cls, value: str | None) -> str | None:
        if value is not None and not value.strip():
            raise ValueError("Button payload must be non-empty when provided.")
        return value


class ButtonParseResult(NamedTuple):
    """Outcome of :meth:`ResponseRegistry.try_parse_button`.

    ``button`` is set when allowed fields form a valid model. ``unknown_keys``
    lists disallowed mapping keys (ignored for the model). ``error`` is a
    human-readable shape/type problem when ``button`` is ``None``.
    """

    button: ResponseButton | None
    unknown_keys: tuple[str, ...]
    error: str | None


def _has_evaluable_condition(condition: str | None) -> bool:
    """Return whether ``select_variant`` should evaluate *condition* against memory.

    Used only at delivery time in :meth:`ResponseRegistry.select_variant`.

    A variant is treated as a **default** (fallback) row when this returns
    ``False``: ``condition`` is ``None`` or whitespace-only. Those rows are not
    passed to :func:`~rasa.mantle.skills.conditions.evaluate_expression`.

    Train-time validation rejects empty ``condition`` strings in YAML; this
    helper covers the runtime edge (programmatic registries, partial merges)
    so blank conditions behave like defaults instead of evaluation errors.
    """
    return condition is not None and not is_empty_prose_if_condition(condition)


class ResponseDefinition(BaseModel):
    """One response variant (text, optional condition, buttons, and metadata)."""

    model_config = ConfigDict(frozen=True)

    text: str
    rephrase: bool = False
    """When ``True``, the orchestrator rewords *text* via a dedicated LLM call."""
    condition: str | None = None
    """Memory expression gating this variant (``session.<namespace>.<entry> …``)."""
    buttons: tuple[ResponseButton, ...] = Field(default_factory=tuple)
    """Static buttons authored on this variant. Empty when the variant has none."""
    button_source: str | None = None
    """Local tool that supplies this variant's buttons at delivery time."""
    metadata: dict[str, Any] = Field(default_factory=dict)
    """Authoring metadata from ``responses.yml`` (e.g. ``rephrase``).

    Stamped onto ``BotUttered.metadata`` at delivery so clients see the full
    variant metadata dict, not only the ``rephrase`` flag used internally.
    """

    @model_validator(mode="after")
    def _validate_button_definition(self) -> ResponseDefinition:
        if self.buttons and self.button_source is not None:
            raise ValueError(
                "A response variant cannot define buttons and button_source."
            )
        if self.button_source is not None and not self.button_source.strip():
            raise ValueError("Button source must be non-empty.")
        return self


class RegisteredResponse(BaseModel):
    """All variants registered under one response name."""

    model_config = ConfigDict(frozen=True)

    variants: tuple[ResponseDefinition, ...] = Field(default_factory=tuple)

    @property
    def default_variant(self) -> ResponseDefinition | None:
        """Return the CRV fallback row (first variant with no ``condition``)."""
        for variant in self.variants:
            if variant.condition is None:
                return variant
        return None


class ResponseRegistry(BaseModel):
    """Flat mapping of response name → :class:`RegisteredResponse`."""

    model_config = ConfigDict(frozen=True)

    responses: dict[str, RegisteredResponse] = Field(default_factory=dict)

    @field_validator("responses", mode="before")
    @classmethod
    def _coerce_legacy_entries(cls, value: Any) -> dict[str, RegisteredResponse]:
        """Coerce shorthand registry values into :class:`RegisteredResponse`.

        Supports plain text, single definitions, and variant lists so
        registries built programmatically or merged from partial sources
        share the same shape as :meth:`from_yaml` output.
        """
        if not isinstance(value, dict):
            raise ValidationError(
                code=_INVALID_RESPONSES_MAPPING_CODE,
                event_info=(
                    "responses must be a mapping of name to text, definition, or "
                    "variants"
                ),
            )
        coerced: dict[str, RegisteredResponse] = {}
        for name, entry in value.items():
            coerced[str(name)] = cls._coerce_registered_response(entry)
        return coerced

    @staticmethod
    def _coerce_registered_response(entry: Any) -> RegisteredResponse:
        if isinstance(entry, RegisteredResponse):
            return entry
        if isinstance(entry, str):
            return RegisteredResponse(variants=(ResponseDefinition(text=entry),))
        if isinstance(entry, ResponseDefinition):
            return RegisteredResponse(variants=(entry,))
        if isinstance(entry, (list, tuple)):
            return RegisteredResponse(variants=tuple(entry))
        raise ValidationError(
            code=_INVALID_RESPONSE_ENTRY_CODE,
            event_info=(
                "each response must be text, a ResponseDefinition, a variant list, "
                "or a RegisteredResponse"
            ),
        )

    def get(self, name: str) -> str | None:
        """Return text ``select_variant`` would pick with empty memory, if any."""
        definition = self.select_variant(name, {})
        return definition.text if definition is not None else None

    def get_definition(self, name: str) -> ResponseDefinition | None:
        """Return the variant ``select_variant`` would pick with empty memory."""
        return self.select_variant(name, {})

    def get_variants(self, name: str) -> tuple[ResponseDefinition, ...]:
        """Return every variant for *name*, or an empty tuple if missing."""
        registered = self.responses.get(name)
        return registered.variants if registered is not None else ()

    def select_variant(
        self, name: str, memory_values: dict[str, Any]
    ) -> ResponseDefinition | None:
        """Return the response variant to deliver for *name* given current memory.

        Conditioned variants are evaluated in YAML order; the first whose
        ``condition`` is true wins. Rows with no ``condition`` (or whitespace-
        only ``condition``) are defaults and are not evaluated. Evaluation
        errors skip that variant (same stance as skill ``requires:`` gating).
        When no conditioned variant matches, the first default row is returned.
        Legacy responses with no conditions at all resolve to the first variant.
        When every variant is conditioned and none match (including when every
        condition raises
        :class:`~rasa.mantle.skills.conditions.ConditionEvaluationError`),
        returns ``None`` — the same signal as a missing response name. Delivery
        (:meth:`~rasa.mantle.orchestration.skill_executor.SkillExecutor.resolve_response_name`)
        therefore applies the pre-existing missing-name fallback.

        Args:
            name: Response name as declared in ``responses.yml``.
            memory_values: Current readable memory snapshot, keyed by
                namespaced slot name (``skill_id.entry``).

        Returns:
            The selected :class:`ResponseDefinition`, or ``None`` when *name*
            is missing, has no variants, or every variant is conditioned and
            none match (fail closed; delivery equals missing-name fallback).
        """
        registered = self.responses.get(name)
        if registered is None or not registered.variants:
            return None

        variants = registered.variants
        for variant in variants:
            if not _has_evaluable_condition(variant.condition):
                continue
            try:
                if evaluate_expression(variant.condition, memory_values):
                    return variant
            except ConditionEvaluationError as exc:
                structlogger.debug(
                    "mantle.responses.condition_evaluation_failed",
                    utterance=name,
                    condition=variant.condition,
                    error=str(exc),
                )
        defaults = [
            variant
            for variant in variants
            if not _has_evaluable_condition(variant.condition)
        ]
        if defaults:
            return defaults[0]
        return None

    @classmethod
    def from_yaml(cls, path: Path) -> "ResponseRegistry":
        """Load a response registry from a YAML file.

        Expected format::

            responses:
              utter_hello:
                - text: "Hello!"
              utter_goodbye:
                - text: "Goodbye!"
                  metadata:
                    rephrase: true
              utter_card_replacement_fee:
                - text: "Standard replacement is free."
                - text: "Expedited replacement carries a fee."
                  condition: 'session.card_replace.replacement_reason == "lost"'
              utter_ask_shipping:
                - text: "Rush or standard?"
                  buttons:
                    - title: Rush
                      payload: "set:session.card_replace.shipping=rush"
                    - title: Standard

        Every variant is stored. At delivery,
        :meth:`ResponseRegistry.select_variant` picks one variant from memory;
        each variant keeps its own ``metadata.rephrase``.

        Returns an empty registry if the file does not exist, is blank, or
        does not contain a ``responses:`` key.
        """
        if not path.exists():
            return cls()
        with path.open(encoding="utf-8") as fh:
            raw = yaml.safe_load(fh) or {}

        entries = raw.get(RESPONSES_YAML_KEY)
        if not isinstance(entries, dict):
            return cls()

        parsed: dict[str, RegisteredResponse] = {}
        for name, variants in entries.items():
            registered = cls._parse_variants(variants)
            if registered is not None:
                parsed[str(name)] = registered
        return cls(responses=parsed)

    @staticmethod
    def _parse_variants(variants: object) -> RegisteredResponse | None:
        """Parse a YAML variant list into a :class:`RegisteredResponse`."""
        if not isinstance(variants, list) or not variants:
            return None
        parsed: list[ResponseDefinition] = []
        for variant in variants:
            parsed.append(ResponseRegistry._parse_variant(variant))
        return RegisteredResponse(variants=tuple(parsed))

    @staticmethod
    def _parse_variant(variant: object) -> ResponseDefinition:
        if isinstance(variant, dict):
            unknown_keys = sorted(set(variant) - ALLOWED_VARIANT_KEYS)
            if unknown_keys:
                raise ValidationError(
                    code=_INVALID_RESPONSE_VARIANT_CODE,
                    event_info=(
                        "Unknown response variant key(s): "
                        f"{', '.join(repr(key) for key in unknown_keys)}. "
                        f"Allowed keys: {', '.join(sorted(ALLOWED_VARIANT_KEYS))}."
                    ),
                )
            text_raw = variant.get(VARIANT_TEXT_KEY, "")
            text = "" if text_raw is None else str(text_raw)
            metadata_raw = variant.get(VARIANT_METADATA_KEY)
            metadata = ResponseRegistry._parse_variant_metadata(metadata_raw)
            rephrase = bool(metadata.get(METADATA_REPHRASE_KEY))
            condition = ResponseRegistry._parse_optional_string_field(
                variant, VARIANT_CONDITION_KEY
            )
            buttons, button_source = ResponseRegistry._parse_buttons(
                variant.get(VARIANT_BUTTONS_KEY)
            )
            return ResponseDefinition(
                text=text,
                rephrase=rephrase,
                condition=condition,
                buttons=buttons,
                button_source=button_source,
                metadata=metadata,
            )
        if isinstance(variant, (str, int, float, bool)):
            return ResponseDefinition(text=str(variant))
        raise ValidationError(
            code=_INVALID_RESPONSE_VARIANT_CODE,
            event_info=(
                "each response variant must be a mapping with a text field or a "
                "scalar text value"
            ),
        )

    @staticmethod
    def _parse_variant_metadata(raw: object) -> dict[str, Any]:
        """Return a shallow copy of variant ``metadata`` when present."""
        if not isinstance(raw, dict):
            return {}
        return dict(raw)

    @staticmethod
    def _parse_optional_string_field(variant: dict[str, Any], key: str) -> str | None:
        """Return a string field from *variant*, or ``None`` when omitted."""
        raw = variant.get(key)
        if raw is None:
            return None
        if isinstance(raw, str):
            return raw
        raise ValidationError(
            code=_INVALID_RESPONSE_VARIANT_CODE,
            event_info=f"Response variant {key!r} must be a string.",
        )

    @staticmethod
    def _parse_buttons(
        raw: object,
    ) -> tuple[tuple[ResponseButton, ...], str | None]:
        """Parse static buttons or a dynamic button source."""
        if raw is None:
            return (), None
        if isinstance(raw, dict):
            unknown_keys = sorted(set(raw) - ALLOWED_BUTTON_SOURCE_KEYS)
            if unknown_keys:
                raise ValidationError(
                    code=_INVALID_RESPONSE_VARIANT_CODE,
                    event_info=(
                        "Unknown response button source key(s): "
                        f"{', '.join(repr(key) for key in unknown_keys)}. "
                        f"Allowed keys: {VARIANT_BUTTONS_SOURCE_KEY}."
                    ),
                )
            source = raw.get(VARIANT_BUTTONS_SOURCE_KEY)
            if not isinstance(source, str) or not source.strip():
                raise ValidationError(
                    code=_INVALID_RESPONSE_VARIANT_CODE,
                    event_info="Response button source must be a non-empty string.",
                )
            return (), source.strip()
        if not isinstance(raw, list):
            raise ValidationError(
                code=_INVALID_RESPONSE_VARIANT_CODE,
                event_info=(
                    f"Response variant {VARIANT_BUTTONS_KEY!r} must be a list of "
                    "mappings or a mapping with a source tool."
                ),
            )
        return (
            tuple(
                ResponseRegistry.parse_button(item, button_index=index)
                for index, item in enumerate(raw)
            ),
            None,
        )

    @staticmethod
    def try_parse_button(item: object) -> ButtonParseResult:
        """Parse one button mapping without raising.

        Returns a :class:`ButtonParseResult`. Unknown keys are reported and
        ignored when building the model. A non-``None`` ``error`` means the
        mapping could not be turned into a :class:`ResponseButton` (caller maps
        it to a finding or :class:`~rasa.exceptions.ValidationError`).
        """
        if not isinstance(item, dict):
            return ButtonParseResult(
                button=None,
                unknown_keys=(),
                error="Each response button must be a mapping with a title field.",
            )

        unknown_keys = tuple(
            sorted(str(key) for key in set(item) - ALLOWED_BUTTON_KEYS)
        )
        allowed_item = {
            key: value for key, value in item.items() if str(key) in ALLOWED_BUTTON_KEYS
        }

        title_raw = allowed_item.get(BUTTON_TITLE_KEY)
        if title_raw is None:
            return ButtonParseResult(
                button=None,
                unknown_keys=unknown_keys,
                error="Each response button must include a non-empty title.",
            )
        if not isinstance(title_raw, str):
            return ButtonParseResult(
                button=None,
                unknown_keys=unknown_keys,
                error=(
                    "Each response button title must be a string; quote labels "
                    'such as "Yes" or "42".'
                ),
            )
        if not title_raw.strip():
            return ButtonParseResult(
                button=None,
                unknown_keys=unknown_keys,
                error="Each response button must include a non-empty title.",
            )

        try:
            payload = ResponseRegistry._parse_button_payload(allowed_item)
        except ValidationError as exc:
            return ButtonParseResult(
                button=None, unknown_keys=unknown_keys, error=str(exc.info)
            )

        return ButtonParseResult(
            button=ResponseButton(title=title_raw, payload=payload),
            unknown_keys=unknown_keys,
            error=None,
        )

    @staticmethod
    def parse_button(
        item: object, *, button_index: int | None = None
    ) -> ResponseButton:
        """Parse one button mapping into a :class:`ResponseButton`.

        Raises:
            ValidationError: On unknown keys or shape/type problems.
        """
        result = ResponseRegistry.try_parse_button(item)
        if result.unknown_keys:
            keys_text = ", ".join(repr(key) for key in result.unknown_keys)
            allowed_text = ", ".join(sorted(ALLOWED_BUTTON_KEYS))
            scope = f"button {button_index} " if button_index is not None else ""
            raise ValidationError(
                code=_INVALID_RESPONSE_VARIANT_CODE,
                event_info=(
                    f"{scope}has unknown response button key(s): {keys_text}. "
                    f"Allowed keys: {allowed_text}."
                ),
            )
        if result.error is not None:
            raise ValidationError(
                code=_INVALID_RESPONSE_VARIANT_CODE,
                event_info=result.error,
            )
        if result.button is None:
            raise ValidationError(
                code=_INVALID_RESPONSE_VARIANT_CODE,
                event_info="Each response button must be a mapping with a title field.",
            )
        return result.button

    @staticmethod
    def _parse_button_payload(item: dict[str, Any]) -> str | None:
        """Return a button payload string, or ``None`` when the key is omitted."""
        if BUTTON_PAYLOAD_KEY not in item:
            return None
        payload_raw = item.get(BUTTON_PAYLOAD_KEY)
        if payload_raw is None or (
            isinstance(payload_raw, str) and not payload_raw.strip()
        ):
            raise ValidationError(
                code=_INVALID_RESPONSE_VARIANT_CODE,
                event_info=(
                    "Each response button must include a non-empty payload "
                    "when ``payload`` is provided; omit the key to send the title."
                ),
            )
        if not isinstance(payload_raw, str):
            raise ValidationError(
                code=_INVALID_RESPONSE_VARIANT_CODE,
                event_info=f"Response variant {BUTTON_PAYLOAD_KEY!r} must be a string.",
            )
        return payload_raw

    def merge(self, other: "ResponseRegistry") -> "ResponseRegistry":
        """Return a new registry with *self* overriding *other* on duplicate keys."""
        merged = {**other.responses, **self.responses}
        return ResponseRegistry(responses=merged)
